  1	import { z } from 'zod';
  2	import type { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
  3	import { LedgerStore } from '../storage/ledger-store.js';
  4	import { loadRegistry, findByFolderName } from '../storage/repository-registry.js';
  5	import { KnowledgeStoreManager } from '../storage/knowledge-store.js';
  6	import { resolveLedgerRoot, deriveRepoName } from '../utils/ledger-root.js';
  7	import type { ProjectMeta } from '../schema/project-meta.js';
  8	import type { RepositoryEntry } from '../schema/repository-registry.js';
  9	import type { Insight } from '../schema/knowledge.js';
 10	
 11	// ─── Input Schema ─────────────────────────────────────────────────────────
 12	
 13	const GetRepositoryContextSchema = z.object({
 14	  cwd_path: z
 15	    .string()
 16	    .optional()
 17	    .describe(
 18	      'Absolute path to the workspace root directory. Used to derive the repository name ' +
 19	      'when repository_name is not provided. Ignored when repository_name is supplied.'
 20	    ),
 21	  repository_name: z
 22	    .string()
 23	    .optional()
 24	    .describe(
 25	      'Explicit repository name to look up in the registry. When provided, cwd_path ' +
 26	      'is not used for name derivation. Treated as both the ledger folder name and the ' +
 27	      'registry lookup key.'
 28	    ),
 29	  include_insights: z
 30	    .boolean()
 31	    .optional()
 32	    .default(true)
 33	    .describe(
 34	      'When true (default), the response includes relevant_insights[] queried from the ' +
 35	      'knowledge store. Set to false to omit insights and reduce response size.'
 36	    ),
 37	  max_projects: z
 38	    .number()
 39	    .int()
 40	    .positive()
 41	    .optional()
 42	    .default(5)
 43	    .describe(
 44	      'Maximum number of projects to return in the projects[] array, sorted by date_created ' +
 45	      'descending (most recent first). Defaults to 5.'
 46	    ),
 47	});
 48	
 49	// ─── Response Shape ───────────────────────────────────────────────────────
 50	
 51	/**
 52	 * A single project entry returned in the projects[] array.
 53	 * Derived from ProjectMeta with a curated subset of fields.
 54	 */
 55	interface ProjectEntry {
 56	  slug: string;
 57	  plan_path: string;
 58	  status: string;
 59	  date_created: string;
 60	  last_updated: string;
 61	  title?: string;
 62	  outcome_summary: string | null;
 63	  progress_pct?: number;
 64	}
 65	
 66	/**
 67	 * The full structured response from ledger_get_repository_context.
 68	 */
 69	interface RepositoryContextResponse {
 70	  repository_name: string;
 71	  repository_id: string | null;
 72	  repository_label: string | null;
 73	  total_projects: number;
 74	  strategic_vision: RepositoryEntry['vision'] | null;
 75	  projects: ProjectEntry[];
 76	  relevant_insights: Insight[];
 77	}
 78	
 79	// ─── Handler ──────────────────────────────────────────────────────────────
 80	
 81	async function getRepositoryContext(
 82	  args: z.infer<typeof GetRepositoryContextSchema>
 83	): Promise<{ content: Array<{ type: 'text'; text: string }>; isError?: boolean }> {
 84	  try {
 85	    const ledgerRoot = resolveLedgerRoot();
 86	
 87	    // 1. Resolve repository name
 88	    let repositoryName: string;
 89	    if (args.repository_name) {
 90	      repositoryName = args.repository_name;
 91	    } else if (args.cwd_path) {
 92	      // Derive from the workspace path (same logic as LedgerStore constructor)
 93	      repositoryName = deriveRepoName(
 94	        // deriveRepoName expects a plan folder path — construct a synthetic one
 95	        // that places the repo root 4 levels above cwd_path (the conventional layout)
 96	        `${args.cwd_path}/docs/agents/plans/synthetic-slug`
 97	      );
 98	    } else {
 99	      return {
100	        content: [

 1	import { readFile, access, readdir, copyFile, rename } from 'fs/promises';
 2	import { join } from 'path';
 3	import { constants } from 'fs';
 4	import { RootIndexSchema, type RootIndex } from '../schema/root-index.js';
 5	import {
 6	  WorkPackageDetailSchema,
 7	  type WorkPackageDetail,
 8	} from '../schema/work-package.js';
 9	import { ProjectMetaSchema, type ProjectMeta } from '../schema/project-meta.js';
10	import { atomicWriteJson } from './atomic-writer.js';
11	import { withLock } from './file-lock.js';
12	import { resolveLedgerRoot, projectSlugFromPath, inferProjectRootFromPlanPath, deriveRepoName } from '../utils/ledger-root.js';
13	import { SAFE_SLUG_REGEX } from '../utils/constants.js';
14	import { now, parseTimestamp } from '../utils/timestamp.js';
15	import { computePassedStages, computeProjectProgress } from '../utils/workflow-helpers.js';
16	
17	/**
18	 * Optional enrichment fields written into `.meta.json` alongside core
19	 * project metadata. Passed to `writeProjectMeta()` by every sync method
20	 * and `writeRootIndex()` so the project-list fast path can avoid
21	 * re-reading root-index files.
22	 */
23	export interface MetaCacheUpdates {
24	  total_work_packages?: number;
25	  pending_work_packages?: number;
26	  progress_pct?: number;
27	  project_name?: string | null;
28	  repository_name?: string | null;
29	  outcome_summary?: string | null;
30	  runner?: string;
31	  runner_client?: string;
32	  runner_version?: string;
33	}
34	
35	/**
36	 * Thrown by `LedgerStore.renameSlug()` when the target slug directory already
37	 * exists on disk (i.e. the slug is taken by another project).
38	 */
39	export class SlugConflictError extends Error {
40	  constructor(slug: string) {
41	    super(`Slug already in use: "${slug}".`);
42	    this.name = 'SlugConflictError';
43	  }
44	}
45	
46	/**
47	 * Central storage abstraction for ledger file I/O.
48	 *
49	 * All reads validate with Zod schemas.
50	 * All writes use atomic operations and file locking.
51	 *
52	 * Files are stored in the centralized ledger root at `{ledgerRoot}/{repoName}/{slug}/`
53	 * rather than inside the plan folder.
54	 */
55	export class LedgerStore {
56	  public readonly planPath: string;
57	  public readonly slug: string;
58	  public readonly ledgerRoot: string;
59	  public readonly repoName: string;
60	  public readonly storageDir: string;
61	
62	  constructor(projectPath: string, ledgerRoot?: string) {
63	    this.planPath = projectPath;
64	    this.slug = projectSlugFromPath(projectPath);
65	    this.ledgerRoot = ledgerRoot ?? resolveLedgerRoot();
66	    this.repoName = deriveRepoName(projectPath);
67	    this.storageDir = join(this.ledgerRoot, this.repoName, this.slug);
68	  }
69	
70	  // ==================== Path Helpers ====================
71	
72	  private rootIndexPath(): string {
73	    return join(this.storageDir, 'project-ledger.json');
74	  }
