 79	/**
 80	 * Finds the first registry entry whose `folder_names` array contains the
 81	 * given folder name (case-sensitive exact match).
 82	 *
 83	 * This is a pure, synchronous lookup that does not perform any I/O.
 84	 * Call `loadRegistry()` to obtain a registry before passing it here.
 85	 *
 86	 * @param registry   - The in-memory registry to search
 87	 * @param folderName - Workspace folder name to search for
 88	 * @returns The matching `RepositoryEntry`, or `null` if no entry matches
 89	 */
 90	export function findByFolderName(
 91	  registry: RepositoryRegistry,
 92	  folderName: string
 93	): RepositoryEntry | null {
 94	  for (const entry of registry.repositories) {
 95	    if (entry.folder_names.includes(folderName)) {
 96	      return entry;
 97	    }
 98	  }
 99	  return null;
100	}

